54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
108	        if (hasReachedDailyRegistrationLimit()) {
109	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
110	        }
111	        if (hasReachedCityOwnerLimit(owner.getCity())) {
112	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
113	        }
114	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
115	            return new ResponseEntity<>(HttpStatus.CONFLICT);
116	        }
117	        owner.setCity(resolveCity(owner.getCity()));
118	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
119	        owner.setMembershipNumber(membershipNumber);
120	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
121	        owner.setMembershipTier(membershipNumber <= MAX_FOUNDING_OWNERS ? "FOUNDING" : "STANDARD");
122	        this.clinicService.saveOwner(owner);
123	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
124	        headers.setLocation(UriComponentsBuilder.newInstance()
125	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
126	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
132	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
133	        if (currentOwner == null) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        currentOwner.setAddress(ownerFieldsDto.getAddress());
137	        currentOwner.setCity(ownerFieldsDto.getCity());
138	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
139	        currentOwner.setLastName(ownerFieldsDto.getLastName());
140	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
141	        this.clinicService.saveOwner(currentOwner);
142	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Transactional
147	    @Override
148	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        this.clinicService.deleteOwner(owner);
154	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        HttpHeaders headers = new HttpHeaders();
165	        Pet pet = petMapper.toPet(petFieldsDto);
166	        owner.setId(ownerId);
167	        pet.setOwner(owner);
168	        pet.getType().setName(null);
169	        this.clinicService.savePet(pet);
170	        PetDto petDto = petMapper.toPetDto(pet);
171	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
172	            .buildAndExpand(pet.getId()).toUri());
173	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
179	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
180	        if (currentOwner != null) {
181	            Pet currentPet = this.clinicService.findPetById(petId);
182	            if (currentPet != null) {
183	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
184	                currentPet.setName(petFieldsDto.getName());
185	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
186	                this.clinicService.savePet(currentPet);
187	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
188	            }
189	        }
190	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
196	        HttpHeaders headers = new HttpHeaders();
197	        Visit visit = visitMapper.toVisit(visitFieldsDto);
198	        Pet pet = new Pet();
199	        pet.setId(petId);
200	        visit.setPet(pet);
201	        this.clinicService.saveVisit(visit);
202	        VisitDto visitDto = visitMapper.toVisitDto(visit);
203	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
204	            .buildAndExpand(visit.getId()).toUri());
205	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
206	    }
207	
208	
209	    /**
210	     * The number of owners at the head of the registration sequence that receive the
211	     * {@code 'FOUNDING'} membership tier. The first {@value #MAX_FOUNDING_OWNERS} owners ever
212	     * created are {@code 'FOUNDING'}; all later owners are {@code 'STANDARD'}.
213	     */
214	    private static final int MAX_FOUNDING_OWNERS = 100;
215	
216	    /**
217	     * The maximum number of owners that may be registered on any single calendar day.
218	     */
219	    private static final long MAX_DAILY_REGISTRATIONS = 20;
220	
221	    /**
222	     * Determines whether the daily owner-registration limit has already been reached. Owners are
223	     * counted by their {@link Owner#getRegistrationDate() registration date}, so once
224	     * {@value #MAX_DAILY_REGISTRATIONS} owners have been registered with today's date, no further
225	     * owners may be created today.
226	     *
227	     * @return {@code true} if today's registration limit has been reached
228	     */
229	    private boolean hasReachedDailyRegistrationLimit() {
230	        LocalDate today = LocalDate.now();
231	        long registeredToday = this.clinicService.findAllOwners().stream()
232	            .filter(existing -> today.equals(existing.getRegistrationDate()))
233	            .count();
234	        return registeredToday >= MAX_DAILY_REGISTRATIONS;
235	    }
236	
237	    /**
238	     * The maximum number of owners that may be registered in any single city.
239	     */
240	    private static final long MAX_OWNERS_PER_CITY = 8;
241	
242	    /**
243	     * Determines whether the given city has already reached its owner limit. Owners are matched to
244	     * the city using {@link #normalize(String)}, so the count ignores letter case and any
245	     * surrounding or repeated whitespace. Once {@value #MAX_OWNERS_PER_CITY} owners live in a city,
246	     * no further owners may be created there.
247	     *
248	     * @param city the city of the new owner, may be {@code null}
249	     * @return {@code true} if the city already contains {@value #MAX_OWNERS_PER_CITY} owners
250	     */
251	    private boolean hasReachedCityOwnerLimit(String city) {
252	        String normalized = normalize(city);
253	        long ownersInCity = this.clinicService.findAllOwners().stream()
254	            .filter(existing -> Objects.equals(normalize(existing.getCity()), normalized))
255	            .count();
256	        return ownersInCity >= MAX_OWNERS_PER_CITY;
257	    }
258	
259	    /**
260	     * Builds the customer code for a newly created owner, formatted as
261	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
262	     * already registered in that city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
263	     *
264	     * @param city the city of the new owner
265	     * @return the assigned customer code
266	     */
267	    private String nextCustomerCode(String city) {
268	        long ownersInCity = this.clinicService.findAllOwners().stream()
269	            .filter(existing -> Objects.equals(
270	                normalize(existing.getCity()), normalize(city)))
271	            .count();
272	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
273	    }
274	
275	    /**
276	     * Resolves the city to store for a newly created owner. The city is title-cased (so
277	     * {@code "new york"} becomes {@code "New York"}), unless an owner already lives in that
278	     * city, in which case the existing owner's exact spelling of the city name is reused. Cities
279	     * are matched using {@link #normalize(String)}, so the match ignores letter case and any
280	     * surrounding or repeated whitespace.
281	     *
282	     * @param city the city supplied for the new owner, may be {@code null}
283	     * @return the city to store, or {@code null} if the input was {@code null}
284	     */
285	    private String resolveCity(String city) {
286	        if (city == null) {
287	            return null;
288	        }
289	        String normalized = normalize(city);
290	        if (!normalized.isEmpty()) {
291	            for (Owner existing : this.clinicService.findAllOwners()) {
292	                if (normalized.equals(normalize(existing.getCity()))) {
293	                    return existing.getCity();
294	                }
295	            }
296	        }
297	        return toTitleCase(city);
298	    }
299	
300	    /**
301	     * Title-cases free-form text by upper-casing the first letter of each whitespace-separated word
302	     * and lower-casing the remaining letters, preserving the original whitespace. For example
303	     * {@code "new  YORK"} becomes {@code "New  York"}.
304	     *
305	     * @param value the raw value, never {@code null}
306	     * @return the title-cased value
307	     */
308	    private static String toTitleCase(String value) {
309	        StringBuilder result = new StringBuilder(value.length());
310	        boolean startOfWord = true;
311	        for (int i = 0; i < value.length(); i++) {
312	            char c = value.charAt(i);
313	            if (Character.isWhitespace(c)) {
314	                startOfWord = true;
315	                result.append(c);
316	            } else if (startOfWord) {
317	                result.append(Character.toTitleCase(c));
318	                startOfWord = false;
319	            } else {
320	                result.append(Character.toLowerCase(c));
321	            }
322	        }
323	        return result.toString();
324	    }
325	
326	    /**
327	     * Determines whether the given telephone number is already used by any other owner.
328	     *
329	     * @param owner the candidate owner
330	     * @return {@code true} if an owner with the same telephone number already exists in the data store
331	     */
332	    private boolean isDuplicateOwner(Owner owner) {
333	        return this.clinicService.findAllOwners().stream()
334	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
335	    }
336	
337	    /**
338	     * Determines whether the given email address is already used by any other owner. An owner
339	     * without an email address is never considered a duplicate on this criterion. Email addresses
340	     * are compared using {@link #normalize(String)} so the check ignores letter case and any
341	     * surrounding or repeated whitespace.
342	     *
343	     * @param owner the candidate owner
344	     * @return {@code true} if the owner provides an email already used by an existing owner
345	     */
346	    private boolean isDuplicateEmail(Owner owner) {
347	        String email = normalize(owner.getEmail());
348	        if (email.isEmpty()) {
349	            return false;
350	        }
351	        return this.clinicService.findAllOwners().stream()
352	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
353	    }
354	
355	    /**
356	     * Normalizes a telephone number to digits only by stripping spaces, dashes and parentheses, so
357	     * that a value such as {@code "(613) 555-0100"} is stored and compared as {@code "6135550100"}.
358	     * This is applied before an owner is stored and before the telephone-uniqueness check, so two
359	     * differently formatted representations of the same number are treated as duplicates. A
360	     * {@code null} value is returned unchanged.
361	     *
362	     * @param telephone the raw telephone number, may be {@code null}
363	     * @return the digits-only telephone number, or {@code null} if the input was {@code null}
364	     */
365	    private static String normalizeTelephone(String telephone) {
366	        if (telephone == null) {
367	            return null;
368	        }
369	        return telephone.replaceAll("[\\s()-]", "");
370	    }
371	
372	    /**
373	     * Normalizes free-form text for duplicate detection so that comparisons ignore letter case and
374	     * surrounding or repeated whitespace: the value is trimmed, runs of internal whitespace are
375	     * collapsed to a single space and the result is lower-cased. This is what makes
376	     * {@code "  john   smith "} and {@code "John Smith"} count as the same value when detecting
377	     * duplicates. A {@code null} value normalizes to the empty string.
378	     *
379	     * @param value the raw value, may be {@code null}
380	     * @return the normalized value, never {@code null}
381	     */
382	    private static String normalize(String value) {
383	        if (value == null) {
384	            return "";
385	        }
386	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
387	    }
388	
389	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
390	    @Override
391	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
392	        Owner owner = this.clinicService.findOwnerById(ownerId);
393	        if (owner != null) {
394	            Pet pet = owner.getPet(petId);
395	            if (pet != null) {
396	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
397	            }
398	        }
399	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
400	    }
401	}
